svg.script:
{
  "metadata": {"title": "Multi-Cloud Architecture", "projectName": "Food Delivery System", "description": "Distributed cloud infrastructure across multiple cloud providers", "version": "1.0", "mode": "light"},
  "config": {"layout": {"canvasWidth": 1920, "canvasHeight": 1080}, "styling": {"mode": "light", "canvasColor": "#FFFFFF", "fillColor": "#E5E5E5", "strokeColor": "#1A1A1A"}},
  "data": {
    "cloudProviders": [
      {"id": "aws", "name": "AWS", "x": 200, "y": 220, "width": 520, "height": 720},
      {"id": "azure", "name": "Azure", "x": 750, "y": 220, "width": 520, "height": 720},
      {"id": "gcp", "name": "Google Cloud", "x": 1300, "y": 220, "width": 520, "height": 720}
    ],
    "integrations": [
      {"from": "aws", "to": "azure", "type": "data-sync"},
      {"from": "azure", "to": "gcp", "type": "data-sync"},
      {"from": "gcp", "to": "aws", "type": "data-sync"}
    ]
  }
}

(function() {
  const dataElement = document.currentScript.closest('svg').querySelector('#multi-cloud-data');
  if (!dataElement) return;
  try {
    const data = JSON.parse(dataElement.textContent);
    console.log('[Multi-Cloud Architecture Data] Loaded:', data.metadata.title);
  } catch (e) {
    console.error('[Multi-Cloud Architecture] Invalid JSON:', e.message);
  }
})();
